mapper.select:
SELECT *
FROM lunaerp_production_yarn_order_item
WHERE order_id = #{orderId}
  AND deleted = 1
  AND tenant_id = #{tenantId}
ORDER BY id ASC

mapper.update:
UPDATE lunaerp_production_yarn_order_item
SET deleted = 0,
    updater = #{updater},
    update_time = #{updateTime}
WHERE order_id = #{orderId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_production_yarn_order_item
WHERE order_id = #{orderId}
  AND deleted = 1
  AND tenant_id = #{tenantId}
